starter.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int score = in.nextInt();
        int tier;
        if (score >= 600) {
            tier = 2;
        } else if (score >= 800) {
            tier = 3;
        } else {
            tier = 1;
        }
        System.out.println(tier);
    }
}

