#include <iostream>
using namespace std;

int main() {
    int score;
    cin >> score;
    int tier;
    if (score >= 600) {
        tier = 2;
    } else if (score >= 800) {
        tier = 3;
    } else {
        tier = 1;
    }
    cout << tier << endl;
    return 0;
}

